import type { ControlScheme, PlayerProfile } from '../contracts';
import { GAME_CONFIG } from '../config/GameConfig';
import { COURSE_SUMMARIES, DEFAULT_COURSE_ID, RANDOM_COURSE_ID, getCourse } from '../courses';
import { buildLeaderboardStandings, renderLeaderboard } from '../leaderboard';
import './ui.css';

type Screen = 'main' | 'play' | 'custom' | 'ranked' | 'settings' | 'profile' | 'leaderboard';
type Mode = 'play' | 'custom' | 'ranked';

export interface UISettings {
  controlScheme: ControlScheme;
  quality: 'low' | 'medium' | 'high' | 'ultra';
  volume: number;
  reducedMotion: boolean;
}

export interface SetupDTO {
  players: number;
  bots: number;
  holes: 9 | 18;
  courseId: string;
}

export interface ProfileDTO extends PlayerProfile {
  level: number;
  xp: number;
  xpNext: number;
  matches: number;
  wins: number;
  bestRound: number;
}

export interface UIActions {
  navigate?(screen: Screen): void;
  startMatch?(mode: Mode, setup: SetupDTO): void;
  saveSettings?(settings: UISettings): void;
}

export interface AppUIOptions {
  initialCourseId?: string;
  playerRating?: number;
}

const profile: ProfileDTO = {
  id: 'local-player',
  displayName: 'Putt Pilot',
  kind: 'human',
  ballStyleId: 'classic-white',
  rating: 1240,
  level: 7,
  xp: 680,
  xpNext: 1000,
  matches: 34,
  wins: 11,
  bestRound: 31,
};

const LEADERBOARD_SIZE = 64;

const HTML_ESCAPES: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
};

const esc = (s: string) => s.replace(/[&<>"]/g, c => HTML_ESCAPES[c]!);

const nav = (label: string, to: Screen, primary = false) =>
  `<button class="cpa-btn ${primary ? 'primary' : ''}" data-nav="${to}">${label}</button>`;

const courseOptions = (selected: string) => {
  const courses = COURSE_SUMMARIES.map(c => {
    const attrs = `value="${c.id}" ${c.id === selected ? 'selected' : ''}`;
    const label = `${esc(c.name)} · ${c.holeCount} holes · par ${c.totalPar}`;
    return `<option ${attrs}>${label}</option>`;
  }).join('');
  const isRandom = selected === RANDOM_COURSE_ID;
  const randomAttrs = `value="${RANDOM_COURSE_ID}" ${isRandom ? 'selected' : ''}`;
  return `${courses}<option ${randomAttrs}>Random Tour</option>`;
};

const setupTitle = (mode: Mode) =>
  mode === 'ranked' ? 'Ranked Match' : mode === 'custom' ? 'Custom Game' : 'Quick Play';

const setupSubtitle = (mode: Mode) =>
  mode === 'ranked'
    ? 'Competitive rules are fixed for fair rating play.'
    : 'Choose your match and hit the green.';

const setup = (mode: Mode, courseId: string) => {
  const locked = mode === 'ranked' ? 'disabled' : '';
  const playerOptions = [1, 2, 3, 4, 5, 6, 7, 8]
    .map(n => `<option ${n === 4 ? 'selected' : ''}>${n}</option>`)
    .join('');
  const botOptions = [0, 1, 2, 3, 4, 5, 6, 7]
    .map(n => `<option ${n === 3 ? 'selected' : ''}>${n}</option>`)
    .join('');
  const startLabel = mode === 'ranked' ? 'Find Match' : 'Start Match';
  return [
    '<section class="cpa-screen">',
    `<header>${nav('← Back', 'main')}<b>MATCH SETUP</b></header>`,
    '<main class="cpa-card">',
    `<h2>${setupTitle(mode)}</h2>`,
    `<p>${setupSubtitle(mode)}</p>`,
    '<div class="cpa-grid">',
    `<label>Players<select name="players" ${locked}>${playerOptions}</select></label>`,
    `<label>Bot rivals<select name="bots" ${locked}>${botOptions}</select></label>`,
    `<label>Holes<select name="holes" ${locked}><option>9</option><option>18</option></select></label>`,
    `<label>Course<select name="course" ${locked}>${courseOptions(courseId)}</select></label>`,
    '</div>',
    `<button class="cpa-btn primary wide" data-start="${mode}">${startLabel}</button>`,
    '</main>',
    '</section>',
  ].join('');
};

export class AppUI {
  private screen: Screen = 'main';
  private settings: UISettings = {
    controlScheme: 'drag-power',
    quality: 'high',
    volume: 80,
    reducedMotion: false,
  };
  private courseId: string;
  private playerRating: number;

  constructor(
    private root: HTMLElement,
    private actions: UIActions = {},
    options: AppUIOptions = {},
  ) {
    const requested = options.initialCourseId?.trim();
    this.courseId =
      requested === RANDOM_COURSE_ID
        ? RANDOM_COURSE_ID
        : (getCourse(requested)?.id ?? DEFAULT_COURSE_ID);
    const rating = options.playerRating;
    this.playerRating =
      typeof rating === 'number' && Number.isFinite(rating) ? Math.round(rating) : profile.rating;
    this.render();
  }

  navigate = (s: Screen) => {
    this.screen = s;
    this.actions.navigate?.(s);
    this.render();
  };

  private mainScreen() {
    return [
      '<section class="cpa-screen main">',
      '<div class="hero">',
      '<small>ARCADE MINI GOLF</small>',
      `<h1>${GAME_CONFIG.title}</h1>`,
      '<p>Master wild courses. Outsmart rivals. Chase the perfect putt.</p>',
      '</div>',
      '<nav>',
      nav('Play', 'play', true),
      nav('Ranked', 'ranked'),
      nav('Custom Game', 'custom'),
      nav('Profile', 'profile'),
      nav('Leaderboard', 'leaderboard'),
      nav('Settings', 'settings'),
      '</nav>',
      '<aside>',
      `<strong>${esc(profile.displayName)}</strong>`,
      `<span>Rating ${profile.rating} · Lv. ${profile.level}</span>`,
      '</aside>',
      '</section>',
    ].join('');
  }

  private settingsScreen() {
    const { volume } = this.settings;
    return [
      '<section class="cpa-screen">',
      `<header>${nav('← Back', 'main')}<b>PREFERENCES</b></header>`,
      '<form class="cpa-card form" data-settings>',
      '<h2>Settings</h2>',
      '<label>Shot controls<select name="controls">',
      '<option value="drag-power">Drag to aim & power</option>',
      '<option value="hold-to-charge">Hold to charge</option>',
      '</select></label>',
      '<label>Graphics<select name="quality">',
      '<option>low</option><option>medium</option><option selected>high</option><option>ultra</option>',
      '</select></label>',
      `<label>Master volume <output>${volume}%</output>`,
      `<input name="volume" type="range" min="0" max="100" value="${volume}"></label>`,
      '<label class="check"><input name="motion" type="checkbox"> Reduce interface motion</label>',
      '<button class="cpa-btn primary" type="submit">Save settings</button>',
      '</form>',
      '</section>',
    ].join('');
  }

  private leaderboardScreen() {
    return [
      '<section class="cpa-screen">',
      `<header>${nav('← Back', 'main')}<b>GLOBAL RANKING</b></header>`,
      '<p class="cpa-note" data-leaderboard-summary></p>',
      '<div class="cpa-leaderboard" data-leaderboard></div>',
      '</section>',
    ].join('');
  }

  private profileScreen() {
    const rate = Math.round((profile.wins / profile.matches) * 100);
    const xp = Math.round((profile.xp / profile.xpNext) * 100);
    return [
      '<section class="cpa-screen">',
      `<header>${nav('← Back', 'main')}<b>PLAYER PROFILE</b></header>`,
      '<main class="cpa-card">',
      `<h2>${esc(profile.displayName)}</h2>`,
      `<p>Level ${profile.level} · Rating ${profile.rating}</p>`,
      `<div class="xp"><i style="width:${xp}%"></i></div>`,
      `<p>${profile.xp} / ${profile.xpNext} XP</p>`,
      '<div class="stats">',
      `<div><b>${profile.matches}</b>Matches</div>`,
      `<div><b>${profile.wins}</b>Wins</div>`,
      `<div><b>${rate}%</b>Win rate</div>`,
      `<div><b>${profile.bestRound}</b>Best round</div>`,
      '</div>',
      '</main>',
      '</section>',
    ].join('');
  }

  private view() {
    switch (this.screen) {
      case 'main':
        return this.mainScreen();
      case 'settings':
        return this.settingsScreen();
      case 'leaderboard':
        return this.leaderboardScreen();
      case 'profile':
        return this.profileScreen();
      default:
        return setup(this.screen, this.courseId);
    }
  }

  /** renderLeaderboard builds real DOM, so the board is mounted after the string view is written. */
  private mountLeaderboard() {
    const host = this.root.querySelector<HTMLElement>('[data-leaderboard]');
    if (!host) return;
    const entries = buildLeaderboardStandings({
      count: LEADERBOARD_SIZE,
      player: {
        id: profile.id,
        displayName: profile.displayName,
        rating: this.playerRating,
        ballStyleId: profile.ballStyleId,
        stats: {
          matchesPlayed: profile.matches,
          wins: profile.wins,
          averageStrokes: Math.round((profile.bestRound / 9) * 100) / 100,
        },
      },
    });
    const you = entries.find(entry => entry.id === profile.id);
    const summary = this.root.querySelector<HTMLElement>('[data-leaderboard-summary]');
    if (summary && you) {
      summary.textContent = `You are #${you.rank} of ${entries.length} · Rating ${you.rating}`;
    }
    host.append(renderLeaderboard(entries, { highlightPlayerId: profile.id }));
  }

  private render() {
    this.root.innerHTML = this.view();
    this.root.querySelectorAll<HTMLElement>('[data-nav]').forEach(x => {
      x.onclick = () => this.navigate(x.dataset.nav as Screen);
    });

    const range = this.root.querySelector<HTMLInputElement>('input[type=range]');
    if (range) {
      range.oninput = () => {
        const o = range.parentElement?.querySelector('output');
        if (o) o.textContent = range.value + '%';
      };
    }

    const form = this.root.querySelector<HTMLFormElement>('[data-settings]');
    if (form) {
      form.onsubmit = e => {
        e.preventDefault();
        const f = new FormData(form);
        this.settings = {
          controlScheme: String(f.get('controls')) as ControlScheme,
          quality: String(f.get('quality')) as UISettings['quality'],
          volume: Number(f.get('volume')),
          reducedMotion: f.get('motion') === 'on',
        };
        this.actions.saveSettings?.(this.settings);
        this.navigate('main');
      };
    }

    const course = this.root.querySelector<HTMLSelectElement>('[name="course"]');
    if (course) {
      course.onchange = () => {
        this.courseId = course.value;
      };
    }

    const start = this.root.querySelector<HTMLElement>('[data-start]');
    if (start) {
      start.onclick = () => {
        const mode = start.dataset.start as Mode;
        const get = (n: string) =>
          this.root.querySelector<HTMLSelectElement>(`[name="${n}"]`)?.value;
        this.actions.startMatch?.(mode, {
          players: Number(get('players') || 4),
          bots: Number(get('bots') || 3),
          holes: Number(get('holes') || 9) as 9 | 18,
          courseId: get('course') || this.courseId,
        });
      };
    }

    if (this.screen === 'leaderboard') this.mountLeaderboard();
  }
}

